import math


def td_residuals(
    rewards: list[float],
    values: list[float],
    gamma: float,
) -> list[float]:
    if len(values) != len(rewards) + 1:
        raise ValueError("values must have length len(rewards)+1")
    if not math.isfinite(gamma) or not 0.0 <= gamma <= 1.0:
        raise ValueError("gamma must lie in [0, 1]")
    numbers = [*rewards, *values]
    if not all(math.isfinite(float(x)) for x in numbers):
        raise ValueError("inputs must be finite")

    return [
        float(rewards[t]) + gamma * float(values[t + 1]) - float(values[t])
        for t in range(len(rewards))
    ]
```

Для терминального перехода в общем коде нужна отдельная маска бутстрэппинга. В задаче последняя ценность уже задана нулём.

```python
import math


def informative_group_probability(p: float, group_size: int) -> float:
    p = float(p)
    if not math.isfinite(p) or not 0.0 <= p <= 1.0:
        raise ValueError("p must lie in [0, 1]")
    if isinstance(group_size, bool) or not isinstance(group_size, int) or group_size < 1:
        raise ValueError("group_size must be a positive integer")
    if p in (0.0, 1.0):
        return 0.0

    at_least_one_success = -math.expm1(group_size * math.log1p(-p))
    all_success = math.exp(group_size * math.log(p))
    return max(0.0, min(1.0, at_least_one_success - all_success))
```

`expm1` и `log1p` уменьшают потерю точности при малом $p$.

